import{_ as o,a,b as r}from"./chunks/670056eddd6101802804.DvpGrezl.js";import{_ as l,C as i,o as s,c as n,j as t,a as u,E as h,a6 as d}from"./chunks/framework.CnPv4DE1.js";const P=JSON.parse('{"title":"当一个失败者——如果你想要快乐","description":"","frontmatter":{"title":"当一个失败者——如果你想要快乐","originalTitle":"Be A Loser – If You Want To Be Happy","date":"2025-06-12","originalUrl":"https://thedankoe.com/letters/be-a-loser-if-you-want-to-be-happy/","minutes":12,"sourceHash":"71ec1adbe4ebc9865ea7c499a3f56f5ee99dddf8cd3f9b1997088b3d20ca352c","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/be-a-loser-if-you-want-to-be-happy/"}]]},"headers":[],"relativePath":"letters/be-a-loser-if-you-want-to-be-happy.md","filePath":"letters/be-a-loser-if-you-want-to-be-happy.md"}'),g={name:"letters/be-a-loser-if-you-want-to-be-happy.md"};function c(b,p,m,f,q,_){const e=i("ArticleMeta");return s(),n("div",null,[p[0]||(p[0]=t("h1",{id:"当一个失败者——如果你想要快乐",tabindex:"-1"},[u("当一个失败者——如果你想要快乐 "),t("a",{class:"header-anchor",href:"#当一个失败者——如果你想要快乐","aria-label":'Permalink to "当一个失败者——如果你想要快乐"'},"​")],-1)),h(e),p[1]||(p[1]=d('<p>如果你想要快乐,那就当一个失败者。</p><p>让你的父母觉得你没有走他们的路是愚蠢的。</p><p>即使你的朋友不相信你,也要开始创业。</p><p>研究那些似乎没人在乎的兴趣。</p><p>因为西方式的成功观念是错误的。你想要的生活并不在一张学位证书、一份高薪工作、一个排满社交义务和活动的日历、用来掩饰孤独的空洞人际关系、买更多东西,或用娱乐腐蚀大脑的另一端。</p><p>东方式的成功观念也是错误的。拒绝显现的世界,去探索你内心世界的复杂性,这确实是一种有价值的追求——而且比以往任何时候都更有价值,但它常常导致人们排斥现实的整整一个维度,把自己封闭起来,无法获得那种无法仅靠孤立的灵修而找到的更深层的快乐。</p><p>生活不能仅仅归结为西方式的“做”,也不能仅仅归结为东方式的“在”,而是二者的整合——一种“成为”。</p><p>现在,“快乐”是一个令人困惑的词。</p><p>每个人都有自己对它的理解和定义,坦白说,你永远无法维持一种持续的快乐巅峰状态。大脑并不是这样运作的。快乐只有在与一个悲伤的参照点相比较时才存在。快乐是一种意识的<em>状态</em>。而状态从来不是永恒的。</p><p>出于这个原因,我们不妨用“成功”这个词,并以一种能让你终于开始朝更好生活行动起来的方式来定义它。</p><hr><p>温和提醒:</p><p>“30天打造盈利个人品牌”挑战赛将在4天后开始。</p><p>如果你有想要与世界分享、以打造现代职业生涯的兴趣、技能或专业知识,<a href="https://stan.store/thedankoe/p/build-a-profitable-personal-brand-in-30-days" target="_blank" rel="noreferrer">可以考虑报名参加。</a></p><h2 id="一种全新的成功范式" tabindex="-1">一种全新的成功范式 <a class="header-anchor" href="#一种全新的成功范式" aria-label="Permalink to &quot;一种全新的成功范式&quot;">​</a></h2><blockquote><p>追求“有用”会比追求“快乐”让你更快乐得多。</p></blockquote><p>字典对“成功”的定义是循环论证式的:</p><p>“成功的程度或衡量。”</p><p>或者,“有利或期望中的结果。”</p><p>这在微观层面实现某件事时是有意义的,比如赚到1000美元这个具体目标,因为你可以在银行账户里看到它,但当我们把它应用到宏观层面时,会发生什么呢?</p><p>当你搜索关于成功的进一步定义时,你会得到一堆博客文章,给你列出19条成功的定义,大意都差不多是:<em>挑战自我、学习、成长、永远尽力而为、拥有一个可以称之为家的地方。</em></p><p>哇。真是明智。真有洞见。</p><p>但当我们深入探究现实的4个维度时,我们会发现一种更有用得多的应用,它超越了过去十年来困扰我们的那些肤浅的自助式解读。</p><p><img src="'+o+'" alt=""></p><p>现实的四个维度,或者说四种视角,是:</p><ul><li><strong>内在个体(主观)</strong> —— 我们的情绪、思想和体验。</li><li><strong>外在个体(客观)</strong> —— 我们如何衡量大脑或身体的行为,这往往与我们的体验相关(比如,多巴胺信号预示着一种动机感)。</li><li><strong>内在集体(主观)</strong> —— 一个群体共享的价值观、道德观或信念。从某种意义上说,文化就是一种共享的心智。</li><li><strong>外在集体(客观)</strong> —— 维系文明社会运转的经济、政治和社会系统。</li></ul><p>我称它们为“维度”,因为它们各自都以一种日益复杂和深化的自然层级形式发展——就像外部四象限从原子到分子到细胞到有机体的演进,而内部则从自我中心到族群中心再到世界中心的价值体系演进。</p><p><img src="'+a+'" alt=""></p><p>西方思想倾向于重视客观的、科学的、物质主义的层面,而这又反过来影响主观层面——也就是我们所成长的文化,它塑造了我们对世界的看法。我们把世界简化为原子,并追逐物质上的成功。</p><p>东方思想则倾向于重视相反的一面。掌控内在世界,培育社群,并与外部顺流而行。</p><p>这两者的问题在于,它们往往会排斥另一方的有效性,而不是从两者中都取其所用,以一种有意义的方式来规划我们的人生。</p><p>如果你把更高的意识状态(内在个体)简化为仅仅是源于由原子构成的大脑中的神经递质,那么你几乎永远不会体验到、甚至都不会察觉到这些状态,更别提达到一个更高的发展基线,为你的生活增添一层平静与愉悦了。</p><p>如果你被灌输去否定金钱、科学和地位追求,后果是双重的:第一,你让那些意识水平低于你的人去建造你所生活的这个世界,而按你的标准来看,这个世界是“邪恶的”。第二,你无法解决那些无法靠放下执念和打坐冥想来解决的问题,这会把你进一步压向压力状态,削弱你的灵性。物质层面的问题往往无法靠纯粹的精神解决方案来解决。</p><p>如果我们参考心理学、神经科学、永恒哲学以及现代生活的现状——涵盖所有维度——我们会发现,“快乐”的一个可能定义,是正在取得进步、为超越自身的某种更大事物做出贡献、以及管理情绪波动的能力这三者的结合。</p><p>实现目标带来的多巴胺、帮助他人带来的成就感、以及掌控你对外部触发因素和内在反复思虑的反应方式,这些为你生活中应该包含的东西提供了相当有力的论据——至少是我们能塞进一句听起来不错的话里的那部分。</p><p>这带来了一个问题,也带来了一个疑问:</p><p>首先,社会的结构方式是这样的:到你成年时,你的心智早已被灌输了关于成功的种种信念。这个版本的成功来自于接受教育,被训练成那个社会中某个特定角色,直到你“熬够了年头”,才能停止工作。</p><p>第二,我们该如何去追求一种全新版本的成功?</p><p>一种能让我们不再回望自己的选择而心生懊悔的成功?</p><h2 id="成功的关键在于成为一个有用的失败者" tabindex="-1">成功的关键在于成为一个有用的失败者 <a class="header-anchor" href="#成功的关键在于成为一个有用的失败者" aria-label="Permalink to &quot;成功的关键在于成为一个有用的失败者&quot;">​</a></h2><blockquote><p>要改变世界,我们必须从自身开始;而从自身开始最重要的是意图。这个意图必须是去理解我们自己,而不是把它留给别人去转变自身,或是通过左派或右派的革命来带来某种被修饰过的改变。</p><p>——克里希那穆提</p></blockquote><p>如果你想掌控自己的快乐,你必须掌控自己的人生。</p><p>虽然完全的掌控并非总是可能,但至少你必须承认,通过审视自己所做的选择,你是能够影响自己成功程度的。</p><p>所有选择中最重要的选择,是拒绝那条在你出生时就已被铺好的路。</p><p>是带着意图去行动。是主动生成目标,而不是被动接受目标。是把别人可能投射到你身上的建议、观点和信念,看作地图上的一小块碎片,而不是领土本身,更绝不是法律。</p><p>但当你完成了人生这项任务时,别人不会为你高兴,因为他们没能做到同样的事。他们对自己的心智没有丝毫的掌控力。他们会想尽一切办法,让你觉得自己是错的、愚蠢的、被误导的。他们会把你看作一个失败者,即便他们内心默默渴望能加入你的行列。</p><h3 id="_1-掌控自己" tabindex="-1">1)掌控自己 <a class="header-anchor" href="#_1-掌控自己" aria-label="Permalink to &quot;1)掌控自己&quot;">​</a></h3><p>几乎没人践行那个能带来全部改变的习惯:</p><p>自我反思。</p><p>我可以给你一些改善自己的建议,但没有什么能胜过对过去错误的清醒觉察。因为一旦你意识到——彻底残酷地意识到——那个错误,它就不会再发生。你意识到的错误越多,你就越朝着你本该前往的方向前进。</p><p>掌控你<em>个人的、内在的</em>世界,是你与外部整个世界互动的基础。如果你想要金钱,你必须把自己培养到足够有用,能够服务于一个社群、系统或组织。如果你不想孤独,你也必须做同样的事,去找到值得的朋友和伴侣。</p><p>你该如何追求自我掌控?</p><p>你要升级。</p><p>“发展路线”就像电子游戏中技能树上的各种能力。</p><p><img src="'+r+'" alt=""></p><p>一旦你达到一定的经验等级,就可以选择给智力、耐力之类的特质加“点”。这样做能解锁更多的机会。它通过用深层问题取代浅层问题,让生活变得更容易。</p><p>在发展心理学中,有一长串可以发展的路线清单。以下是AI给我列出的内容:</p><p><strong>核心路线:</strong></p><ul><li><strong>认知路线</strong> —— 心智推理、逻辑与概念性思维</li><li><strong>道德路线</strong> —— 伦理推理以及关怀/公正取向</li><li><strong>情感路线</strong> —— 情绪智力与情感成熟度</li><li><strong>精神路线</strong> —— 精神智力与超个人发展</li><li><strong>人际路线</strong> —— 社交技能与关系智力</li><li><strong>性心理路线</strong> —— 性与亲密关系的发展</li><li><strong>自我认同路线</strong> —— 自我意识与自我发展</li></ul><p><strong>其他路线:</strong></p><ul><li><strong>审美路线</strong> —— 艺术鉴赏与创造性表达</li><li><strong>躯体路线</strong> —— 身体觉知与身体智力</li><li><strong>价值观路线</strong> —— 个人认为重要或有意义的事物</li><li><strong>需求路线</strong> —— 人类需求与动机的层级</li><li><strong>世界观路线</strong> —— 一个人如何看待和解读现实</li><li><strong>数理路线</strong> —— 数字与空间推理</li><li><strong>音乐路线</strong> —— 音乐智力与鉴赏力</li><li><strong>动觉路线</strong> —— 身体运动智力</li></ul><p>这里我想说一个至关重要的观点,它可能听起来有点疯狂。</p><p>很多人把过去的思想家和导师捧上神坛。而事实是,他们中的许多人只把一条路线——精神或思辨路线——发展到极限,却忽视了其余的路线。有不少案例中,我们视为智者的导师,却被证实存在性别歧视、种族歧视,而且从更实际的角度来说,他们如此固守于自己的某种世界观,以至于把金钱这个现代生活的必要部分妖魔化。</p><p>我们不再生活在单一的地点、单一特定文化之中,不再只能获取有限的信息了。我们与世界的知识相连,处在一个多元世界观交融的大熔炉之中。</p><p>当今世界中那些高于平均水平的人,拥有比历史上任何其他人都更充分发展自己的潜力。</p><p>不要把这视为理所当然。</p><h3 id="_2-真正的教育" tabindex="-1">2)真正的教育 <a class="header-anchor" href="#_2-真正的教育" aria-label="Permalink to &quot;2)真正的教育&quot;">​</a></h3><p>真正的教育不是记忆,而是发现。</p><p>真正的教育发生在你意识到——当别人告诉你该学什么时,你其实什么都学不到——之后,于是你自己掌控局面,成为自己的老师。</p><p>当你学习一个体系提供给你的信息时,这些信息会使该体系的结果产生偏向。你没有创建这套课程。你没有资助这套课程。而无论你怎样试图为它辩护,当今建立在工业价值基础之上的教育体系,其目的就是培养有用的劳动者。如果你不以自己的兴趣为指南针进行自我教育,默认的选项就是把你的注意力收窄到那个最终目标上。你会错过那些为你量身定制的机会。</p><p>真正的教育是对真理的追求。</p><p>真相并不存在于别人嘴里说出的话语中。</p><p>虽然学习没有&quot;正确&quot;的方式，但只要遵循自然的指南针，你就不会走偏：</p><ul><li>追求一个自发生成的目标（高度感兴趣且有意义）</li><li>将其拆解为实现它所必需的核心技能</li><li>将这些核心技能拆解为基本要素</li><li>花40多个小时去实验各种&quot;技巧&quot;</li><li>记录哪些对你的情况有效，哪些无效</li><li>经常反思你的进展，完善你的目标，继续学习</li></ul><p>知识是假设，实践是实验，结果是数据。这是一种通过内在来验证外在的研究。</p><p>你必须学习到足够多的程度，才能对什么能带来结果有一个自信的猜测，然后你会意识到，技能习得实际上是&quot;技巧堆叠&quot;。</p><p>你并不是在&quot;学习&quot;PhotoShop、AI或写作。</p><p>你有一个目标。你找到一个技巧去尝试，比如使用某个写作框架，或者用某种特定方式去选取你想要遮罩的物体。你去看看这个技巧对<em>你的</em>思维和情境这个独特的环境是否有效。</p><p>你把这个技巧加入你的工具箱，然后继续前进，直到你能创造出足够的价值，以此为生。</p><h3 id="_3-现代归属感" tabindex="-1">3）现代归属感 <a class="header-anchor" href="#_3-现代归属感" aria-label="Permalink to &quot;3）现代归属感&quot;">​</a></h3><p>孤独有它存在的意义。</p><p>短暂的孤立和专注时期，对培养独立思考能力非常有帮助。但这并不能改变我们是社会性生物这一事实。我认为，归属感是紧随食物、水、庇护所和稳定环境之后的一项基本需求，这在目前应该没有争议。</p><p>信息时代的缺点在于，世界变得如此碎片化。</p><p>你很少能在自己的物理位置上找到有相似兴趣和目标的人，因为多亏了我们所接触的信息，我们能够发现这些兴趣的机会本来就很少见。</p><p>现在，尽管渴望过去某个时代（比如&quot;我出生错了年代！&quot;）听起来很诱人，但这实际上根本无法实现。你就在这里。你身处这个充满科技与互联互通的美丽世界。你只需要学会以一种不会让你变成一个挂在多巴胺静脉注射管上、口水直流的骸骨袋的方式去使用它。</p><p>尽管社交媒体有诸多缺点，但它弥补了这些不足——它让我们能够筛选自己接收信息的来源，并与几乎任何拥有互联网连接的人建立关系。</p><p>解决方案很简单：减少随机性。</p><p>那个不惜一切代价抓住你注意力的&quot;为你推荐&quot;页面，必须节制使用，只用它来发现那些与你有共同兴趣的人。一旦找到他们，就与他们建立联系。把他们的动态安全地保存下来。深入探究他们所传授的内容。</p><p>正如我在自我掌控中所说明的那样，人际关系也是一条发展路线。要成为一个能与任何人交谈的人，没有速成的方法。我会在某个时候就此写一篇专门的文章。</p><p>在那之前，让我们把这一切串联起来。</p><h3 id="_4-为社会做出贡献" tabindex="-1">4）为社会做出贡献 <a class="header-anchor" href="#_4-为社会做出贡献" aria-label="Permalink to &quot;4）为社会做出贡献&quot;">​</a></h3><p>你在提升自己（个体内在）。</p><p>你在追求真相（个体外在）。</p><p>你在培育社群（集体内在）。</p><p>所有这些以各种方式融合在一起，带来深刻的满足感。</p><p>但还有一个部分。一个所有人都为之苦恼的部分。</p><p>体制。游戏规则。企业职业生涯。那个被谈论得太多以至于变得令人厌烦的事实——&quot;每个人&quot;都讨厌自己的工作。</p><p>那个&quot;我该拿我的人生怎么办？&quot;的问题。</p><p>让我们把这件事说得几乎过于简单：</p><p><em>找到你所关心的事物和他人所关心的事物之间的交集。</em></p><p>创造的行为。这就是将一切串联在一起的东西。变得有价值。将你的思想塑造成值得与世界分享的东西。不是被指派去创造什么，而是自己选择创造什么。</p><p>但同样，如果我们犯了那个关键性错误——把某一个维度的优先级置于另一个之上，我们最终会成为一个饥饿的艺术家。我们为了满足自我而创作。我们用那些关于&quot;要真实、创造<em>你</em>想要的东西&quot;的老生常谈来为自己的创作欲望找理由。同样，这样做的时候，你是在无意识地选择给自己强加更多的问题，同时放弃了解决这些问题的能力。</p><p>一个更有价值的目标是：因做自己而获得报酬。</p><p>这包含两个部分：</p><ul><li>成为一个足够有价值、值得被付费的人</li><li>理解他人的渴望，从而创造出他们愿意为之付费的东西</li></ul><p>在大多数情况下，这需要企业家精神。</p><p>我对一直往上爬这件事没有任何异议，直到你能找到那1%的工作——它能给予你自主权（这是一项被文献证实的心理需求），让你去创造你想要的东西。</p><p>但如果你以批判的眼光审视这个世界，你会发现，当我说&quot;机会从未如此之多&quot;时，这不仅仅是那些不了解你处境的人随口说出的一句陈词滥调。</p><p>每一个读到这篇文章的人都拥有互联网连接。</p><p>因此，每一个读到这篇文章的人都有能力将自己的知识、兴趣和创作发布到这个世界上。</p><p>从那时起，你所要做的，就是回归自我教育的过程。</p><p>互联网是一个巨大的反馈循环。</p><p>如果人们不关心你所提供的东西，那也不过是一个可以被识别、被假设、被转化为实验并被解决的问题。</p><p>感谢阅读。</p><p>希望这篇文章能给你一些启发。</p><p>——丹（Dan）</p><p>还有一件事。</p><p>如果你想尝试企业家这条路，&quot;<a href="https://stan.store/thedankoe/p/build-a-profitable-personal-brand-in-30-days" target="_blank" rel="noreferrer">30天打造盈利个人品牌</a>&quot;挑战将在4天后开始。</p><p>尽管个人品牌听起来可能有点老套，但它囊括了我们在这里讨论的一切：通过自我掌控变得有价值，通过自我教育拥有值得表达的内容，找到你在其他地方找不到的、与你志同道合的人，以及因做自己而获得报酬。</p><p>如果这听起来有用，可以考虑加入。</p><hr><p><a href="/en/letters/be-a-loser-if-you-want-to-be-happy">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',122))])}const x=l(g,[["render",c]]);export{P as __pageData,x as default};
